program:
(()=>{

const $ = id => document.getElementById(id);
const WA = FMI.phone;   /* couple's WhatsApp for real invitations */
const TARGET = FMI.target;

/* guest name from ?to=Kumar-Family */
let guest = "";
try {
  const raw = new URLSearchParams(FMI.search).get("to") || "";
  guest = raw.replace(/[-_+]+/g, " ").replace(/\s+/g, " ").trim().slice(0, 40);
  guest = guest.split(" ").map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(" ");
} catch (e) {}
if (guest) {
  $("dear").textContent = "Dear " + guest + ",";
  $("r-name").value = guest;
  document.title = "Dear " + guest + " · Siva & Divya's wedding";
}

/* music */
const bgm = $("bgm"), musicBtn = $("music");
let musicWanted = false;
function setMusic(on){
  musicWanted = on;
  if (on) { const p = bgm.play(); if (p) p.catch(() => { musicWanted = false; paintMusic(); }); }
  else bgm.pause();
  paintMusic();
}
function paintMusic(){
  const on = musicWanted;
  musicBtn.classList.toggle("on", on);
  musicBtn.setAttribute("aria-pressed", String(on));
  musicBtn.setAttribute("aria-label", on ? "Pause music" : "Play music");
}
musicBtn.addEventListener("click", () => setMusic(!musicWanted));

/* temple doors */
$("open").addEventListener("click", () => {
  $("gate").classList.add("open");
  document.body.classList.remove("locked");
  setMusic(true);
  setTimeout(() => { $("gate").hidden = true; }, matchMedia("(prefers-reduced-motion: reduce)").matches ? 500 : 1900);
});

/* film */
const film = $("film-video"), filmPlay = $("film-play");
let resumeMusic = false;
filmPlay.addEventListener("click", () => {
  resumeMusic = musicWanted;
  setMusic(false);
  film.muted = false;
  film.controls = true;
  filmPlay.hidden = true;
  const p = film.play();
  if (p) p.catch(() => { film.controls = true; filmPlay.hidden = false; });
});
film.addEventListener("play", () => { filmPlay.hidden = true; if (musicWanted) { resumeMusic = true; setMusic(false); } });
film.addEventListener("ended", () => { if (resumeMusic) setMusic(true); });

/* countdown */
const cells = {}; document.querySelectorAll("#count b").forEach(b => cells[b.dataset.u] = b);
function tick(){
  let s = Math.floor((TARGET - Date.now()) / 1000);
  if (s <= 0) { $("count").hidden = true; $("count-note").textContent = "Siva and Divya are married! Thank you for your blessings."; return; }
  const d = Math.floor(s / 86400); s -= d * 86400;
  const h = Math.floor(s / 3600); s -= h * 3600;
  const m = Math.floor(s / 60); s -= m * 60;
  cells.d.textContent = d;
  cells.h.textContent = String(h).padStart(2, "0");
  cells.m.textContent = String(m).padStart(2, "0");
  cells.s.textContent = String(s).padStart(2, "0");
}
tick(); setInterval(tick, 1000);

/* calendar: Apple devices open the .ics, everyone else gets Google Calendar */
const CAL = FMI.calendar({
  reception: { t: "Siva & Divya · Wedding Reception", d: "20270213T123000Z/20270213T163000Z", l: "Mayor Ramanathan Chettiar Centre, R.A. Puram, Chennai" },
  muhurtham: { t: "Siva & Divya · Wedding Muhurtham", d: "20270214T013000Z/20270214T043000Z", l: "Arulmigu Vadapalani Andavar Temple, Vadapalani, Chennai" }
});
const apple = /iPhone|iPad|iPod|Macintosh/.test(navigator.userAgent);
if (!apple) document.querySelectorAll("[data-cal]").forEach(a => {
  const c = CAL[a.dataset.cal];
  a.href = "https://calendar.google.com/calendar/render?action=TEMPLATE&text=" + encodeURIComponent(c.t) + "&dates=" + c.d + "&location=" + encodeURIComponent(c.l) + "&details=" + encodeURIComponent("Invitation: https://findmyinvite.com/");
  a.target = "_blank"; a.rel = "noopener";
});

/* gallery dots */
const gal = $("gal"), dots = [...document.querySelectorAll("#dots i")];
gal.addEventListener("scroll", () => requestAnimationFrame(() => {
  const figs = [...gal.children], mid = gal.scrollLeft + gal.clientWidth / 2;
  let best = 0, bd = Infinity;
  figs.forEach((f, i) => { const c = f.offsetLeft + f.offsetWidth / 2; const dd = Math.abs(c - mid); if (dd < bd) { bd = dd; best = i; } });
  dots.forEach((d, i) => d.classList.toggle("on", i === best));
}), { passive: true });

/* rsvp */
let guests = 2;
const paintGuests = () => $("g-count").textContent = guests;
$("g-minus").addEventListener("click", () => { guests = Math.max(1, guests - 1); paintGuests(); });
$("g-plus").addEventListener("click", () => { guests = Math.min(15, guests + 1); paintGuests(); });
const form = $("rsvp-form");
form.addEventListener("change", () => {
  const yes = form.querySelector("input[name=att]:checked").value === "yes";
  $("att-yes").style.display = yes ? "grid" : "none";
});
form.addEventListener("submit", e => {
  e.preventDefault();
  const name = $("r-name").value.trim();
  if (!name) { $("r-err").hidden = false; $("r-name").focus(); return; }
  $("r-err").hidden = true;
  const yes = form.querySelector("input[name=att]:checked").value === "yes";
  const lines = ["🙏 RSVP · Siva & Divya's wedding", "", "Name: " + name, "Attending: " + (yes ? "Yes, joyfully" : "Sorry, can't make it")];
  if (yes) {
    const fns = [...form.querySelectorAll("input[name=fn]:checked")].map(i => i.value);
    lines.push("Functions: " + (fns.join(", ") || "Not sure yet"));
    lines.push("Guests: " + guests);
    lines.push("Food: " + form.querySelector("input[name=food]:checked").value);
  }
  const msg = $("r-msg").value.trim();
  if (msg) lines.push("Wishes: " + msg);
  const url = "https://wa.me/" + WA + "?text=" + encodeURIComponent(lines.join("\n"));
  const w = FMI.open(url, "_blank");
  if (!w) FMI.open(url);
});

/* share */
function toast(t){ const el = $("toast"); el.textContent = t; el.hidden = false; clearTimeout(toast.t); toast.t = setTimeout(() => el.hidden = true, 2200); }
$("share").addEventListener("click", async () => {
  const url = location.origin + FMI.instanceKey;
  const data = { title: "Siva & Divya · Wedding Invitation", text: "You're invited to Siva & Divya's wedding on 14 February 2027 💐", url };
  try {
    if (navigator.share) { await FMI.share(data); return; }
    await FMI.copyLink(url); toast("Invitation link copied");
  } catch (e) { if (e && e.name !== "AbortError") toast(url); }
});


FMI.ready();
})();
